import { esc } from './ui.js';
import { SOUND_TYPES } from '../core/sound-scan.js';
import { REGIONS } from '../core/regions.js';
import { isBusy } from '../state.js';
export function soundOverview(s) {
    if (!s.scan)
        return '';
    const locked = isBusy(s) ? 'disabled' : '';
    const catalog = s.catalog;
    const query = (s.form['source-query'] || '').toLocaleLowerCase('da-DK').trim();
    const sources = catalog?.sources.filter(source => !query || source.name.toLocaleLowerCase('da-DK').includes(query)).slice(0, 30) || [];
    return `<section class="sound-overview" id="sound-overview"><div class="section-heading compact"><div><h2>1. Hvilke lyde kan vi se?</h2><p>Flere lydtyper kan optræde i samme optagelse. Screeningen giver indikationer, ikke sikker genkendelse.</p></div><label class="field"><span>Land</span><select name="country">${Object.entries(REGIONS).map(([code, region]) => `<option value="${code}" ${code === 'DK' ? 'selected' : 'disabled'}>${esc(region.name)}</option>`).join('')}</select></label></div>
  <div class="sound-cards">${SOUND_TYPES.map(type => {
        const d = s.scan.detections.find(d => d.kind === type.id);
        return `<article class="panel sound-card"><span class="pill ${d.status === 'possible' ? 'lime' : ''}">${d.status === 'possible' ? 'Mulig lydtype' : 'Ingen tydelig indikation'}</span><h3>${esc(type.label)}</h3><p>${esc(d.evidence.join(' '))}</p>${d.segments.length ? `<p class="mono">${d.segments.slice(0, 4).map(segment => `${segment.start.toFixed(0)}–${segment.end.toFixed(0)} s`).join(' · ')}</p>` : ''}${type.id === 'aircraft' ? `<button class="btn btn-secondary btn-small" data-action="aircraft" ${locked}>Undersøg flybaner</button>` : `<p class="small-print">${type.id === 'church_bell' ? 'Stedmatch kræver en reference fra den konkrete kirke.' : 'Eksperimentel screening. Møllestøj er ikke unik nok til stedmatch i denne version.'}</p>`}</article>`;
    }).join('')}</div>
  <div class="panel source-panel"><div class="section-heading compact"><div><h2>2. Sammenlign med danske kilder</h2><p>Kildeplaceringer og lydreferencer er to forskellige datasæt.</p></div><button class="btn btn-secondary btn-small" data-action="import-catalog" ${locked}>Importér katalog / referencer</button></div>
  ${s.catalogError ? `<p class="error-box" role="alert">${esc(s.catalogError)}</p><button class="text-button" data-action="retry-catalog" ${locked}>Prøv igen</button>` : ''}
  ${catalog ? `<p>${catalog.sources.filter(source => source.kind === 'church_bell').length} kirker · ${catalog.sources.filter(source => source.kind === 'wind_turbine').length} vindmøller / parker · ${catalog.references.filter(ref => !ref.synthetic).length} lydreferencer</p><p class="small-print">${esc(catalog.coverage)}</p><p class="source-credit" data-i18n-skip>${esc(catalog.source)} · ${esc(catalog.license)} · ${esc(catalog.fetchedAt.slice(0, 10))}</p>` : '<p>Kildekatalog indlæses …</p>'}
  <h3>Referencer, der ligner din optagelse</h3>${s.sourceMatches.length ? `<p>Disse kilders klang ligner optagelsen. Det bekræfter hverken kirken eller mikrofonens placering.</p><div class="source-matches">${s.sourceMatches.map(m => `<article><strong data-i18n-skip>${esc(m.source.name)}</strong><p>${m.start.toFixed(0)}–${m.end.toFixed(0)} s · ${m.source.lat.toFixed(5)}, ${m.source.lon.toFixed(5)}</p><a href="${esc(m.source.url)}" target="_blank" rel="noopener noreferrer">Se kildens placering</a><p class="small-print" data-i18n-skip>${esc(m.source.provenance)} · ${esc(m.source.license)}</p></article>`).join('')}</div>` : `<p>${catalog?.references.some(ref => !ref.synthetic) ? 'Ingen referencer opfylder kravene til klanglig lighed.' : 'Ingen stedbundne lydreferencer er indlæst. Kortkataloget alene kan ikke stedbestemme lyden.'}</p>`}
  <details><summary>Opbyg et referencebibliotek</summary><p>Vælg en kendt kirke, og åbn en separat optagelse af dens klokker. Referencen behandles lokalt og kan eksporteres til senere brug. Brug en ren optagelse med flere klokkeslag.</p>
  <div class="signal-fields"><label class="field"><span>Søg efter kirke</span><input name="source-query" value="${esc(s.form['source-query'] || '')}" maxlength="100" ${locked}></label><button class="btn btn-secondary btn-small" data-action="filter-sources" ${locked}>Find kilder</button></div>
  <label class="field"><span>Kendt kilde · højst 30 søgeresultater</span><select name="reference-source" ${locked}><option value="">Vælg kirke</option>${sources.filter(source => source.kind === 'church_bell').map(source => `<option value="${esc(source.id)}" ${s.form['reference-source'] === source.id ? 'selected' : ''}>${esc(source.name)} · ${source.lat.toFixed(3)}, ${source.lon.toFixed(3)}</option>`).join('')}</select></label>
  <div class="signal-fields"><label class="field"><span>Referencekilde / ophav</span><input name="reference-provenance" value="${esc(s.form['reference-provenance'] || '')}" placeholder="Egen optagelse ved kirken" maxlength="1000" ${locked}></label><label class="field"><span>Referencens licens</span><input name="reference-license" value="${esc(s.form['reference-license'] || '')}" placeholder="Egen optagelse · privat brug" maxlength="1000" ${locked}></label></div>
  <label class="checkbox-field"><input type="checkbox" name="reference-consent" ${s.form['reference-consent'] === 'yes' ? 'checked' : ''} ${locked}><span>Jeg har ret til at bruge referenceoptagelsen og kender dens kildeplacering.</span></label><label class="checkbox-field"><input type="checkbox" name="reference-synthetic" ${s.form['reference-synthetic'] === 'yes' ? 'checked' : ''} ${locked}><span>Syntetisk testreference · må ikke bruges til stedmatch</span></label><button class="btn btn-secondary btn-small" data-action="reference-audio" ${locked}>Åbn referenceoptagelse og gem reference</button><p class="small-print">Referencefiler gemmes kun ved eksport. Genindlæsning af siden rydder indlæste optagelser og referencer.</p></details></div>
  <div class="scan-actions"><button class="btn btn-secondary" data-action="scan-report" ${locked}>Eksportér lydrapport</button></div>
  <p class="small-print">${s.scan.warnings.map(esc).join(' ')}</p></section>`;
}
